const GC=2, GR=2;
const Q={up:[-0.7071068,0,0,0.7071068],down:[0.7071068,0,0,0.7071068],right:[0,0,-0.7071068,0.7071068],left:[0,0,0.7071068,0.7071068]};
function start(){return {col:0,row:0,moves:0,hint:null,bump:false};}
function hintDir(s){if(s.col<GC)return 'right';if(s.row<GR)return 'up';if(s.col>GC)return 'left';if(s.row>GR)return 'down';return null;}
export function initialState(){return start();}
export function reduce({state,event}){
 if(!event||event.type!=='action')return state;
 const id=event.action!==undefined?event.action:event.id;
 if(id==='reset')return start();
 const won=state.col===GC&&state.row===GR;
 if(id==='hint'){if(won)return state;return Object.assign({},state,{hint:hintDir(state),bump:false});}
 if(won)return state;
 let c=state.col,r=state.row;
 if(id==='up')r++;else if(id==='down')r--;else if(id==='left')c--;else if(id==='right')c++;else return state;
 if(c<0||c>2||r<0||r>2)return Object.assign({},state,{bump:true,hint:null});
 return {col:c,row:r,moves:state.moves+1,hint:null,bump:false};
}
export function evaluate({state}){
 const s=state||start();
 const x=(s.col-1)*1.1, z=(1-s.row)*1.1;
 const won=s.col===GC&&s.row===GR;
 const rem=Math.abs(GC-s.col)+Math.abs(GR-s.row);
 let msg;
 if(won)msg='Goal reached in '+s.moves+' moves!'+(s.moves===4?' Perfect!':'');
 else if(s.hint)msg='Hint: press '+s.hint.charAt(0).toUpperCase()+s.hint.slice(1);
 else if(s.bump)msg='Edge of the board - try another way';
 else if(s.moves===0)msg='Reach the green Goal tile';
 else msg=rem+' steps to go';
 const nodes={token:{position:[x,0.225,z]},status:{text:msg},hintArrow:{visible:!!s.hint&&!won}};
 if(s.hint)nodes.hintArrow.quaternion=Q[s.hint];
 return {nodes,materials:{goalMat:{color:won?'#22c55e':'#3cb371'},tokenMat:{color:won?'#f2c230':'#2f6fd6'}},readouts:{moves:s.moves,remaining:rem},goal:won?{status:'won',message:'You reached the goal in '+s.moves+' moves.'}:{status:'playing'}};
}
